import axios from 'axios';

const API_URL = 'https://localhost:7285/api'; // Backend API URL'si

export const getStore1CategoryStocks = async () => {
    try {
        console.log('API URL:', `${API_URL}/Store1/CategoryStock`); // Debug için URL'i logla
        const response = await axios.get(`${API_URL}/Store1/CategoryStock`, {
            headers: {
                'Accept': 'application/json',
                'Content-Type': 'application/json'
            }
        });
        console.log('API Response:', response.data); // Debug için yanıtı logla
        return response.data;
    } catch (error) {
        console.error('API Error Details:', {
            message: error.message,
            response: error.response?.data,
            status: error.response?.status
        });
        throw error;
    }
};

export const getStore2CategoryStocks = async () => {
    try {
        console.log('API URL:', `${API_URL}/Store2/CategoryStock`);
        const response = await axios.get(`${API_URL}/Store2/CategoryStock`, {
            headers: {
                'Accept': 'application/json',
                'Content-Type': 'application/json'
            }
        });
        console.log('API Response:', response.data);
        return response.data;
    } catch (error) {
        console.error('API Error Details:', {
            message: error.message,
            response: error.response?.data,
            status: error.response?.status
        });
        throw error;
    }
};

export const getStore3CategoryStocks = async () => {
    try {
        const response = await fetch(`${API_URL}/Store3/GetCategoryStocks`);
        const data = await response.json();
        return data;
    } catch (error) {
        console.error('Kategori stok verileri alınırken hata:', error);
        return { success: false, message: 'Kategori stok verileri alınamadı' };
    }
};

export const getStore3AllStocks = async () => {
    try {
        const response = await fetch(`${API_URL}/Store3/StockGetAll`);
        if (!response.ok) {
            throw new Error('Network response was not ok');
        }
        const data = await response.json();
        return data;
    } catch (error) {
        console.error('Stok verileri alınırken hata:', error);
        return { success: false, message: 'Stok verileri alınamadı', error: error.message };
    }
};

export const createStore3Stock = async (stockData) => {
    try {
        const response = await fetch(`${API_URL}/Store3/StockCreate`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(stockData)
        });
        const data = await response.json();
        return data;
    } catch (error) {
        console.error('Stok oluşturulurken hata:', error);
        return { success: false, message: 'Stok oluşturulamadı' };
    }
};

export const createStore3Sale = async (saleData) => {
    try {
        const response = await fetch(`${API_URL}/Store3/SaleCreate`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(saleData)
        });
        const data = await response.json();
        return data;
    } catch (error) {
        console.error('Satış oluşturulurken hata:', error);
        return { success: false, message: 'Satış oluşturulamadı' };
    }
};

export const createStore3Return = async (returnData) => {
    try {
        const response = await fetch(`${API_URL}/Store3/ReturnCreate`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(returnData)
        });
        const data = await response.json();
        return data;
    } catch (error) {
        console.error('İade oluşturulurken hata:', error);
        return { success: false, message: 'İade oluşturulamadı' };
    }
};
